-- 577: Original BrillaPrep WASSCE English Language sprint 3 beta questions, part 7 of 9 (batch wassce-english-sprint3-001).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_577_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_577_guard;
INSERT INTO _migration_577_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_013' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following topics calls for a narrative essay?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Write a story that ends with the words: \"I shall never lend money again.\"","B. Explain how cassava is processed into gari.","C. Should students use mobile phones in school?","D. Describe your favourite teacher."]' AND q.correct_answer IS 'A' AND q.explanation IS 'The instruction "write a story" marks a narrative topic; the gari topic is expository, the phone question argumentative and the teacher topic descriptive. Therefore the correct answer is A: Write a story that ends with the words: "I shall never lend money again.".' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Classify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_013' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_577_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_015' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Before writing an essay in the examination hall, a good candidate first' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. copies a memorised essay onto the answer sheet","B. counts the words in the question","C. plans the main points and their order","D. decorates the answer booklet"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Brief planning — jotting and ordering the main points — keeps the essay relevant and organised; reproducing a memorised essay risks irrelevance, and counting or decorating earns nothing. Therefore the correct answer is C: plans the main points and their order.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_015' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_577_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_022' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_sum' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In summary writing, the instruction to use "your own words" means the candidate should' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. change the writer''s meaning completely","B. express the writer''s ideas in different vocabulary","C. answer in a Ghanaian language","D. give a personal opinion on the topic"]' AND q.correct_answer IS 'B' AND q.explanation IS '"Your own words" means re-expressing the writer''s points in fresh vocabulary — not altering the meaning, switching languages or importing opinions the passage does not contain. Therefore the correct answer is B: express the writer''s ideas in different vocabulary.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_022' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_577_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_031' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a summary question, candidates commonly lose marks by' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. beginning each sentence with a capital letter","B. using complete grammatical sentences","C. writing more sentences than the question demands","D. reading the passage more than once"]' AND q.correct_answer IS 'C' AND q.explanation IS 'When the question specifies one sentence, extra sentences breach the instruction and are penalised; capitals, complete sentences and careful re-reading are virtues, not faults. Therefore the correct answer is C: writing more sentences than the question demands.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_031' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_577_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_034' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In an informal letter to a friend, the date is normally written' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. at the top of the letter, immediately after the writer''s address","B. at the very bottom of the letter","C. after the subscription","D. in the middle of the first paragraph"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The conventional informal layout puts the writer''s address at the top right with the date beneath it; the bottom, after the subscription and mid-paragraph belong to no accepted format. Therefore the correct answer is A: at the top of the letter, immediately after the writer''s address.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_034' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s3_013', 'topic_wassce_p2_eng_ess', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Which of the following topics calls for a narrative essay?', 'multiple_choice', NULL, '["A. Write a story that ends with the words: \"I shall never lend money again.\"","B. Explain how cassava is processed into gari.","C. Should students use mobile phones in school?","D. Describe your favourite teacher."]', 'A', 'The instruction "write a story" marks a narrative topic; the gari topic is expository, the phone question argumentative and the teacher topic descriptive. Therefore the correct answer is A: Write a story that ends with the words: "I shall never lend money again.".', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Classify', 'AO2', NULL, NULL, NULL);
